const counter = {
  count: 0,
  up() {
    this.count += 1;

    return this;
  },
};

const other = { count: 10, up: counter.up };
const step = counter.up().up();
const jump = counter.up.call(other).up();
const up = counter.up;

console.log(step === counter);
console.log(counter.count);
console.log(jump === other);
console.log(other.count);

try {
  up().up();
} catch (error) {
  console.log(error.name);
}
